(1276803, 163589, 93, '<td valign="top">very nice, but a little *too* oversaturated for my tastes.  Seems a little over-sharpened as well.  I''ll give a 7, but know that it could have been more.</td>', 'very nice, but a little *too* oversaturated for my tastes.  Seems a little over-sharpened as well.  I''ll give a 7, but know that it could have been more.', '2005-04-07 07:33:10.000000', NULL, 1),
(1276806, 163452, 93, '<td valign="top">In the future, try and take photographs that you''ll be happy submitting in full dimensions.</td>', 'In the future, try and take photographs that you''ll be happy submitting in full dimensions.', '2005-04-07 07:35:21.000000', NULL, 1),
(1276807, 163577, 36114, '<td valign="top">beautiful</td>', 'beautiful', '2005-04-07 07:36:28.000000', NULL, 1),
