(1277677, 163332, 15810, '<td valign="top">I dont understand why people dont use the maximum pixel dimensions in their submissions. Your shot which is interesting would score much much better at it''s maximum allowable size. At the moment it looks squashed and cluttered.</td>', 'I dont understand why people dont use the maximum pixel dimensions in their submissions. Your shot which is interesting would score much much better at it''s maximum allowable size. At the moment it looks squashed and cluttered.', '2005-04-07 17:03:37.000000', NULL, 1),
(1277679, 163669, 15810, '<td valign="top">Your shot looks hazy and unclear and doesn''t therefore appeal to the eye. Was this taken in a humid environment?</td>', 'Your shot looks hazy and unclear and doesn''t therefore appeal to the eye. Was this taken in a humid environment?', '2005-04-07 17:06:00.000000', NULL, 1),
(1277681, 163186, 15810, '<td valign="top">Nice shot. Like the colours and the textures and the inventive framing.</td>', 'Nice shot. Like the colours and the textures and the inventive framing.', '2005-04-07 17:06:50.000000', NULL, 1),
(1277683, 161478, 32378, '<td valign="top">This seems out of focus or something.  Perhaps it is just overexposed.</td>', 'This seems out of focus or something.  Perhaps it is just overexposed.', '2005-04-07 17:07:18.000000', NULL, 1),
(1277684, 162924, 15810, '<td valign="top">Gorgeous shot, lovely colours and excellent composition. One of my top picks for the challenge and a definite ribbon.</td>', 'Gorgeous shot, lovely colours and excellent composition. One of my top picks for the challenge and a definite ribbon.', '2005-04-07 17:08:01.000000', NULL, 1),
(1277685, 163192, 32378, '<td valign="top">Seems over sharpened or something.  Would have liked it better is you had not turned it on its side to force the C.</td>', 'Seems over sharpened or something.  Would have liked it better is you had not turned it on its side to force the C.', '2005-04-07 17:08:20.000000', NULL, 1),
(1277687, 163453, 32378, '<td valign="top">Right side way overexposed.  Rest of the image needs more color.  It looks like you forced a letter by croping so tightly.</td>', 'Right side way overexposed.  Rest of the image needs more color.  It looks like you forced a letter by croping so tightly.', '2005-04-07 17:09:23.000000', NULL, 1),
