(1277693, 162983, 15810, '<td valign="top">very very well done. Nicely subtle but obvious too. Great work.</td>', 'very very well done. Nicely subtle but obvious too. Great work.', '2005-04-07 17:11:26.000000', NULL, 1),
(1277694, 163201, 32378, '<td valign="top">Seems to dark for me.</td>', 'Seems to dark for me.', '2005-04-07 17:11:34.000000', NULL, 1),
