(1281007, 162403, 33530, '<td valign="top">Although i find this image quite disturbing, i am able to see letters within the image other than what is written (an A formed with the leg and arm with hate carved in it). Without this, i wouldn''t say it fitted the challenge.</td>', 'Although i find this image quite disturbing, i am able to see letters within the image other than what is written (an A formed with the leg and arm with hate carved in it). Without this, i wouldn''t say it fitted the challenge.', '2005-04-09 17:30:53.000000', NULL, 1),
(1281008, 163681, 36188, '<td valign="top">Novel but a little boring - don''t like the lamps either. I personally don''t like the wasted space....but what do I know.</td>', 'Novel but a little boring - don''t like the lamps either. I personally don''t like the wasted space....but what do I know.', '2005-04-09 17:32:53.000000', NULL, 1),
(1281010, 161597, 36188, '<td valign="top">Interesting colouring and unusual subject matter.</td>', 'Interesting colouring and unusual subject matter.', '2005-04-09 17:34:18.000000', NULL, 1),
(1281011, 163254, 21611, '<td valign="top">Very nice shot One of my favorites simple and on target. However nothing inspiring about much of the sky or far ocean. IMHO a tighter crop would have proved a 9. All in all very nice work</td>', 'Very nice shot One of my favorites simple and on target. However nothing inspiring about much of the sky or far ocean. IMHO a tighter crop would have proved a 9. All in all very nice work', '2005-04-09 17:34:30.000000', NULL, 1),
