(1281033, 163563, 21611, '<td valign="top">Excellent composition  simple but clean and crisp meets the challenge perfectly. 8</td>', 'Excellent composition  simple but clean and crisp meets the challenge perfectly. 8', '2005-04-09 17:44:09.000000', NULL, 1),
(1281034, 163186, 21611, '<td valign="top">nice shot, nice use of colour it really brings out the idea. gave it an 8</td>', 'nice shot, nice use of colour it really brings out the idea. gave it an 8', '2005-04-09 17:44:53.000000', NULL, 1),
(1281036, 162919, 36188, '<td valign="top">Nice colouring, shadow effect and the bee even looks real and not staged - well done, a nice study.</td>', 'Nice colouring, shadow effect and the bee even looks real and not staged - well done, a nice study.', '2005-04-09 17:45:13.000000', NULL, 1),
(1281037, 163436, 36188, '<td valign="top">Quite nice - I like the blue effect behind the mottled glass. The wrought iron work is delightfully placed.</td>', 'Quite nice - I like the blue effect behind the mottled glass. The wrought iron work is delightfully placed.', '2005-04-09 17:46:27.000000', NULL, 1),
(1281038, 162782, 21611, '<td valign="top">very nice shot, I think the frame is a bit over powering, still a great shot gave it a 7</td>', 'very nice shot, I think the frame is a bit over powering, still a great shot gave it a 7', '2005-04-09 17:46:41.000000', NULL, 1),
(1281040, 163693, 36188, '<td valign="top">Nice composition highlighting a distant peak. A little too much cloud for me, but nice all the same.</td>', 'Nice composition highlighting a distant peak. A little too much cloud for me, but nice all the same.', '2005-04-09 17:47:36.000000', NULL, 1),
(1281041, 163047, 21611, '<td valign="top">I give up. where are the letters</td>', 'I give up. where are the letters', '2005-04-09 17:47:59.000000', NULL, 1),
