INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1281063, 163552, 36188, '<td valign="top">Very nice, clever composition and nice colouring too. Well done.</td>', 'Very nice, clever composition and nice colouring too. Well done.', '2005-04-09 17:59:19.000000', NULL, 1),
(1281066, 161868, 36188, '<td valign="top">Nice spring photo with good composition, but that is all (for me).</td>', 'Nice spring photo with good composition, but that is all (for me).', '2005-04-09 18:00:18.000000', NULL, 1),
(1281068, 161683, 36188, '<td valign="top">Interesting contrast with the vivid blue of the subject A and the blue and dark sky.<br/>Clever idea.</td>', 'Interesting contrast with the vivid blue of the subject A and the blue and dark sky.Clever idea.', '2005-04-09 18:01:51.000000', NULL, 1),
(1281070, 163319, 33530, '<td valign="top">The image appears out of focus</td>', 'The image appears out of focus', '2005-04-09 18:02:37.000000', NULL, 1),
(1281072, 161839, 36188, '<td valign="top">Don''t like it and don''t understand it. Cluttered and dark, almost depressing.</td>', 'Don''t like it and don''t understand it. Cluttered and dark, almost depressing.', '2005-04-09 18:02:50.000000', NULL, 1),
(1281073, 163426, 36188, '<td valign="top">Points for novelty and patience.</td>', 'Points for novelty and patience.', '2005-04-09 18:03:26.000000', NULL, 1),
(1281078, 162023, 36188, '<td valign="top">Nice study of the wheel and lovely colouring. One can imagine the wheel turning easily. Maybe this shot spent more time in the photoshop than it deed in the composition phase. Lovely all the same.</td>', 'Nice study of the wheel and lovely colouring. One can imagine the wheel turning easily. Maybe this shot spent more time in the photoshop than it deed in the composition phase. Lovely all the same.', '2005-04-09 18:06:33.000000', NULL, 1),
(1281080, 163256, 36188, '<td valign="top">The vivid blue against the brown of the terrain makes a nice relief from the grey sky. I can almost see the clouds moving. Well done.</td>', 'The vivid blue against the brown of the terrain makes a nice relief from the grey sky. I can almost see the clouds moving. Well done.', '2005-04-09 18:08:31.000000', NULL, 1),
(1281081, 163535, 36188, '<td valign="top">Clever idea and nicely framed. I like the single green shoot as the colour focus.<br/></td>', 'Clever idea and nicely framed. I like the single green shoot as the colour focus.', '2005-04-09 18:10:14.000000', NULL, 1),
(1281084, 163595, 36188, '<td valign="top">Unusual and interesting - even if the title isn''t.</td>', 'Unusual and interesting - even if the title isn''t.', '2005-04-09 18:11:09.000000', NULL, 1),
(1281086, 163514, 33256, '<td valign="top">Fabulous detail. Beautifully done.</td>', 'Fabulous detail. Beautifully done.', '2005-04-09 18:12:05.000000', NULL, 1),
(1281087, 163078, 36188, '<td valign="top">Never seen a Ram chewing a blade of grass before? Nice study.</td>', 'Never seen a Ram chewing a blade of grass before? Nice study.', '2005-04-09 18:12:55.000000', NULL, 1),
(1281089, 162236, 33256, '<td valign="top">Very noisy. Top of head cut off. Could have been so much better.</td>', 'Very noisy. Top of head cut off. Could have been so much better.', '2005-04-09 18:14:31.000000', NULL, 1),
(1281091, 163418, 33256, '<td valign="top">Nothing special about this photo. I don''t see how it meets the challenge. Sorry.</td>', 'Nothing special about this photo. I don''t see how it meets the challenge. Sorry.', '2005-04-09 18:16:00.000000', NULL, 1),
(1281092, 163336, 36188, '<td valign="top">Clever - clever - clever! Fun composition and great use of the hands/forearms. Can''t imagine how long it took to set up - but it was worth it.</td>', 'Clever - clever - clever! Fun composition and great use of the hands/forearms. Can''t imagine how long it took to set up - but it was worth it.', '2005-04-09 18:16:06.000000', NULL, 1),
(1281094, 161969, 33256, '<td valign="top">Did you flop this for the purpose of this challenge? :-(</td>', 'Did you flop this for the purpose of this challenge? :-(', '2005-04-09 18:17:09.000000', NULL, 1),
(1281095, 162945, 36188, '<td valign="top">Hard on the eyes....too much blurring in background. Don''t like it sorry.</td>', 'Hard on the eyes....too much blurring in background. Don''t like it sorry.', '2005-04-09 18:17:29.000000', NULL, 1),
(1281098, 163047, 33256, '<td valign="top">Am I missing the letter here? Nice shot. Looks a little dark on my monitor.</td>', 'Am I missing the letter here? Nice shot. Looks a little dark on my monitor.', '2005-04-09 18:19:11.000000', NULL, 1),
(1281099, 163439, 36188, '<td valign="top">The sunset detracts from the vitality of the P subject. So this P has no power for me.</td>', 'The sunset detracts from the vitality of the P subject. So this P has no power for me.', '2005-04-09 18:19:11.000000', NULL, 1),
(1281101, 163539, 33256, '<td valign="top">I like the idea. I would have preferred to see the natural colors.</td>', 'I like the idea. I would have preferred to see the natural colors.', '2005-04-09 18:22:38.000000', NULL, 1),
(1281102, 162403, 36188, '<td valign="top">A little unrealistic - I''ve seen a few of these for real. Nice composition otherwise though. Lovely subject even if she is poorly staged.</td>', 'A little unrealistic - I''ve seen a few of these for real. Nice composition otherwise though. Lovely subject even if she is poorly staged.', '2005-04-09 18:26:34.000000', NULL, 1),
(1281104, 163586, 36188, '<td valign="top">Nice photo and appropriate message. A target and ammunition would have added realism - unless he is trying to fell the tree with thin air?</td>', 'Nice photo and appropriate message. A target and ammunition would have added realism - unless he is trying to fell the tree with thin air?', '2005-04-09 18:30:42.000000', NULL, 1),
(1281105, 163419, 36188, '<td valign="top">No - I prefer the other study behind mottled glass.</td>', 'No - I prefer the other study behind mottled glass.', '2005-04-09 18:31:29.000000', NULL, 1),
(1281106, 163397, 36188, '<td valign="top">Original macro study.</td>', 'Original macro study.', '2005-04-09 18:32:27.000000', NULL, 1),
(1281107, 163701, 36188, '<td valign="top">Lovely sunset image. There are so many poor sunset photos, but this is not one of them. Well done.</td>', 'Lovely sunset image. There are so many poor sunset photos, but this is not one of them. Well done.', '2005-04-09 18:34:50.000000', NULL, 1),
(1281111, 163224, 36188, '<td valign="top">I have problems with falling water, it never seems to come out right. So when I see a good study like this - it is appreciated. Not the best I''ve seen, but pretty good.</td>', 'I have problems with falling water, it never seems to come out right. So when I see a good study like this - it is appreciated. Not the best I''ve seen, but pretty good.', '2005-04-09 18:36:23.000000', NULL, 1),
(1281113, 163412, 36188, '<td valign="top">I''m a fan of bird photography so this is an ideal close-up study for me.<br/>Lovely composition and colour contrast. The bird also looks alive, unlike some I''ve seen.</td>', 'I''m a fan of bird photography so this is an ideal close-up study for me.Lovely composition and colour contrast. The bird also looks alive, unlike some I''ve seen.', '2005-04-09 18:38:53.000000', NULL, 1),
(1281119, 163659, 36188, '<td valign="top">Prefer the other clearer study with the glass and fork. Sorry.</td>', 'Prefer the other clearer study with the glass and fork. Sorry.', '2005-04-09 18:43:04.000000', NULL, 1),
(1281121, 162782, 36188, '<td valign="top">Interesting with an oriental flavour for me. Great composition with the kite and pilot at extreme opposites. Lovely clear background sky and landscape.</td>', 'Interesting with an oriental flavour for me. Great composition with the kite and pilot at extreme opposites. Lovely clear background sky and landscape.', '2005-04-09 18:45:44.000000', NULL, 1),
(1281122, 163418, 33379, '<td valign="top">i give up, what letter</td>', 'i give up, what letter', '2005-04-09 18:46:01.000000', NULL, 1),
(1281123, 162382, 36188, '<td valign="top">Nice study but just doesn''t look real enough for me. A lab photo.</td>', 'Nice study but just doesn''t look real enough for me. A lab photo.', '2005-04-09 18:47:53.000000', NULL, 1),
(1281124, 163700, 36188, '<td valign="top">Indeed! Lovely study of the bridge with a misty background. The pastel shades of the background really make this photo for me. I think I hear a train coming.......</td>', 'Indeed! Lovely study of the bridge with a misty background. The pastel shades of the background really make this photo for me. I think I hear a train coming.......', '2005-04-09 18:50:17.000000', NULL, 1),
(1281125, 163460, 36188, '<td valign="top">Lots of colour and the sweet packets give it some meaning. Quite nice</td>', 'Lots of colour and the sweet packets give it some meaning. Quite nice', '2005-04-09 18:51:47.000000', NULL, 1),
(1281128, 163372, 36188, '<td valign="top">Clever idea but it doesn''t work because of the ''censoring'' to make it appropriate for this site. It might have been more interesting if the dark shadow on the left of the picture had been removed - thus making it less obvious what it is.</td>', 'Clever idea but it doesn''t work because of the ''censoring'' to make it appropriate for this site. It might have been more interesting if the dark shadow on the left of the picture had been removed - thus making it less obvious what it is.', '2005-04-09 18:56:27.000000', NULL, 1),
(1281130, 163183, 36188, '<td valign="top">Good contrast with the grey of the subject and the greenery behind.</td>', 'Good contrast with the grey of the subject and the greenery behind.', '2005-04-09 18:58:33.000000', NULL, 1),
(1281131, 162936, 36188, '<td valign="top">Good subject and nice shadowing complementing the colours of the ring and rock.</td>', 'Good subject and nice shadowing complementing the colours of the ring and rock.', '2005-04-09 18:59:40.000000', NULL, 1),
(1281133, 163566, 36188, '<td valign="top">I am a sucker for vivid blues and this goes well the the metallic bars. Lovely definition of colour.</td>', 'I am a sucker for vivid blues and this goes well the the metallic bars. Lovely definition of colour.', '2005-04-09 19:00:55.000000', NULL, 1),
(1281135, 163694, 36188, '<td valign="top">Nice idea for the Q and well highlighted.</td>', 'Nice idea for the Q and well highlighted.', '2005-04-09 19:02:10.000000', NULL, 1),
(1281136, 163578, 36188, '<td valign="top">Nice family photo, but I''ve seen hundreds of these. A little boring even if the kid is cute.</td>', 'Nice family photo, but I''ve seen hundreds of these. A little boring even if the kid is cute.', '2005-04-09 19:03:48.000000', NULL, 1),
